import{_ as t,c as a,o as s,ag as d}from"./chunks/framework.DCv_I274.js";const m=JSON.parse('{"title":"Artisan commands","description":"","frontmatter":{},"headers":[],"relativePath":"guides/artisan-commands.md","filePath":"guides/artisan-commands.md","lastUpdated":null}'),r={name:"guides/artisan-commands.md"};function o(i,e,c,p,n,h){return s(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="artisan-commands" tabindex="-1">Artisan commands <a class="header-anchor" href="#artisan-commands" aria-label="Permalink to &quot;Artisan commands&quot;">​</a></h1><h2 id="generators-used-for-a-module" tabindex="-1">Generators used for a module <a class="header-anchor" href="#generators-used-for-a-module" aria-label="Permalink to &quot;Generators used for a module&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Creates</th></tr></thead><tbody><tr><td><code>php artisan make:migration create_campuses_table</code></td><td><code>database/migrations/..._create_campuses_table.php</code></td></tr><tr><td><code>php artisan make:model Campus</code></td><td><code>app/Models/Campus.php</code></td></tr><tr><td><code>php artisan make:request CampusRequest</code></td><td><code>app/Http/Requests/CampusRequest.php</code></td></tr><tr><td><code>php artisan make:service v1/modules/CampusService</code></td><td><code>app/Services/v1/modules/CampusService.php</code></td></tr><tr><td><code>php artisan make:resource v1/modules/campus/CampusResource</code></td><td><code>app/Http/Resources/v1/modules/campus/CampusResource.php</code></td></tr><tr><td><code>php artisan make:controller API/v1/modules/CampusController</code></td><td><code>app/Http/Controllers/API/v1/modules/CampusController.php</code></td></tr><tr><td><code>php artisan make:controller Web/CampusPageController</code></td><td><code>app/Http/Controllers/Web/CampusPageController.php</code> (Blade pages)</td></tr><tr><td><code>php artisan make:test CampusTest --pest</code></td><td><code>tests/Feature/CampusTest.php</code></td></tr></tbody></table><h2 id="make-service" tabindex="-1"><code>make:service</code> <a class="header-anchor" href="#make-service" aria-label="Permalink to &quot;`make:service`&quot;">​</a></h2><p>A custom generator (<code>app/Console/Commands/MakeServiceCommand.php</code>) that renders <code>stubs/service.stub</code> into <code>app/Services</code>. Include the subfolder in the name:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make:service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1/modules/CampusService</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # App\\Services\\v1\\modules\\CampusService</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make:service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1/global/ReportService</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # App\\Services\\v1\\global\\ReportService</span></span></code></pre></div><p>Edit <code>stubs/service.stub</code> to change what every new service starts with.</p><h2 id="project-commands" tabindex="-1">Project commands <a class="header-anchor" href="#project-commands" aria-label="Permalink to &quot;Project commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Does</th></tr></thead><tbody><tr><td><code>php artisan auth:purge-refresh-sessions --days=7</code></td><td>Deletes refresh-session rows that expired more than 7 days ago. Schedule it daily</td></tr><tr><td><code>php artisan db:seed --class=RbacSeeder</code></td><td>Re-seeds modules, actions, groups and permissions (additive)</td></tr></tbody></table><h2 id="everyday-commands" tabindex="-1">Everyday commands <a class="header-anchor" href="#everyday-commands" aria-label="Permalink to &quot;Everyday commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Use</th></tr></thead><tbody><tr><td><code>php artisan route:list --path=v1/campuses</code></td><td>Check URLs and middleware of a module</td></tr><tr><td><code>php artisan migrate:fresh --seed</code></td><td>Rebuild the local database from scratch</td></tr><tr><td><code>php artisan scramble:export</code></td><td>Write the OpenAPI spec to <code>api.json</code></td></tr><tr><td><code>php artisan test</code> / <code>./vendor/bin/pest</code></td><td>Run the tests</td></tr><tr><td><code>php artisan optimize:clear</code></td><td>Clear config, route and view caches after changing <code>.env</code></td></tr></tbody></table>',11)])])}const u=t(r,[["render",o]]);export{m as __pageData,u as default};
